def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Enclosed regions are made transparent: identify background-colored
    # components not connected to the border, and replace them with 0.
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            border = False
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                if y == 0 or x == 0 or y == h-1 or x == w-1:
                    border = True
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy, xx = y+dy, x+dx
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == bg and (yy,xx) not in seen:
                        seen.add((yy,xx)); stack.append((yy,xx))
            if not border:
                for y, x in comp:
                    out[y][x] = 0
    return out
